16	#include "aclrtlaunch_sort_values_kernel.h"
17	#include "sort_values_tiling.h"
18	
19	namespace ascend_kernel {
20	
21	constexpr int64_t UB_SORT_CAPACITY = 2048;
22	constexpr int64_t MULTI_CORE_PER_LOOP = 512;
23	constexpr int64_t ONE_LOOP_MAX = 256;
24	
25	static int32_t getDtypeCode(at::ScalarType dtype)
26	{
27	    if (dtype == at::kFloat)     return 0;
28	    if (dtype == at::kHalf)      return 1;
29	    if (dtype == at::kBFloat16)  return 2;
30	    TORCH_CHECK(false, "Unsupported dtype");
31	    return -1;
32	}
33	
34	static void computeTiling(SortValuesTiling* t, int32_t totalRows, int32_t sortLen,
35	                          int32_t dtype, int32_t descending, int32_t totalCores)
36	{
37	    *t = SortValuesTiling{};
38	    t->totalRows = totalRows;
39	    t->sortLen = sortLen;
40	    t->dtype = dtype;
41	    t->descending = descending;
42	
43	    // 32-aligned sort length
44	    int64_t aligned = ((int64_t)sortLen + 31) / 32 * 32;
45	    t->sortNum = static_cast<int32_t>(aligned);
46	
47	    if (sortLen <= static_cast<int32_t>(UB_SORT_CAPACITY)) {
48	        t->tilingMode = SORT_VALUES_MODE_FULLLOAD;
49	        int32_t usedCores = std::min<int32_t>(totalCores, totalRows);
50	        t->coreNum = (usedCores > 0) ? usedCores : 1;
51	        t->needCoreNum = t->coreNum;
52	        return;
53	    }
54	
55	    // Multicore mode: sort each row with multiple cores
56	    t->tilingMode = SORT_VALUES_MODE_MULTICORE;
57	
58	    int32_t perLoop = static_cast<int32_t>(MULTI_CORE_PER_LOOP);
59	    int32_t needCores = std::min<int32_t>(totalCores,
60	        (sortLen + perLoop - 1) / perLoop);
61	    if (needCores < 2) needCores = 2;
62	
63	    t->coreNum = needCores;
64	    t->needCoreNum = needCores;
65	
66	    int32_t perCore = (sortLen + needCores - 1) / needCores;
67	    perCore = ((perCore + 31) / 32) * 32;
68	    int32_t lastCore = sortLen - perCore * (needCores - 1);
69	    if (lastCore <= 0) {
70	        perCore = sortLen / needCores;
71	        perCore = ((perCore + 31) / 32) * 32;
72	        lastCore = sortLen - perCore * (needCores - 1);
73	    }
74	
75	    t->perCoreElements = perCore;
76	    t->lastCoreElements = lastCore;
77	
78	    int32_t loopElem = std::min<int32_t>(perLoop, perCore);
79	    loopElem = ((loopElem + 31) / 32) * 32;
80	
81	    t->perCorePerLoopElements = loopElem;
82	    t->perCoreLoops = (perCore + loopElem - 1) / loopElem;
83	    t->perCoreLastLoopElements = perCore - loopElem * (t->perCoreLoops - 1);
84	
85	    t->lastCorePerLoopElements = loopElem;
86	    t->lastCoreLoops = (lastCore + loopElem - 1) / loopElem;
87	    t->lastCoreLastLoopElements = lastCore - loopElem * (t->lastCoreLoops - 1);
88	
89	    t->oneLoopMaxElements = static_cast<int32_t>(ONE_LOOP_MAX);
90	}
91	
92	at::Tensor sort_values(const at::Tensor& input, int64_t descending)
93	{
94	    TORCH_CHECK(input.dim() == 2, "sort_values expects 2D input [batch, sort_len]");
95	    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
96	
97	    auto dtype = input.scalar_type();
98	    TORCH_CHECK(dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16,
99	                "sort_values supports float32, float16, bfloat16");
100	
101	    int32_t batch = static_cast<int32_t>(input.size(0));
102	    int32_t sortLen = static_cast<int32_t>(input.size(1));
103	    int32_t dtypeCode = getDtypeCode(dtype);
104	    int32_t desc = static_cast<int32_t>(descending ? 1 : 0);
105	
106	    auto output = at::empty_like(input);
107	
108	    // Get platform info
109	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
110	    int64_t totalCores = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
111	    uint64_t ubSize = 0;
112	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
113	
114	    // Compute tiling
115	    at::Tensor tilingCpu = at::empty(
116	        {static_cast<int64_t>(sizeof(SortValuesTiling))},
117	        at::device(at::kCPU).dtype(at::kByte));
118	    auto* tiling = reinterpret_cast<SortValuesTiling*>(tilingCpu.data_ptr());
119	    computeTiling(tiling, batch, sortLen, dtypeCode, desc, static_cast<int32_t>(totalCores));
120	
121	    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
122	
123	    // Workspace for multicore mode
124	    int64_t wsBytes = 0;
125	    if (tiling->tilingMode == SORT_VALUES_MODE_MULTICORE) {
126	        int64_t perCoreFloats = static_cast<int64_t>(tiling->perCoreElements) * 2;  // sort format
127	        int64_t oneBufFloats = static_cast<int64_t>(tiling->needCoreNum) * perCoreFloats;
128	        wsBytes = oneBufFloats * sizeof(float) * 2 + 4096;
129	    }
130	    at::Tensor workspace = at::empty({wsBytes}, input.options().dtype(at::kByte));
131	
132	    // Launch kernel
133	    uint32_t blockDim = static_cast<uint32_t>(tiling->coreNum);
134	    EXEC_KERNEL_CMD(sort_values_kernel, blockDim, input, output, workspace, tilingNpu);
135	
136	    return output;
137	}
138	
