18	    GM_ADDR input, GM_ADDR output, GM_ADDR workspace, GM_ADDR tiling)
19	{
20	    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIV_1_0);
21	    if (g_coreType == AIC) {
22	        return;
23	    }
24	
25	    auto* gmTiling = reinterpret_cast<__gm__ SortValuesTiling*>(tiling);
26	    SortValuesTiling t;
27	    t.tilingMode = gmTiling->tilingMode;
28	    t.totalRows = gmTiling->totalRows;
29	    t.sortLen = gmTiling->sortLen;
30	    t.dtype = gmTiling->dtype;
31	    t.descending = gmTiling->descending;
32	    t.coreNum = gmTiling->coreNum;
33	    t.needCoreNum = gmTiling->needCoreNum;
34	    t.perCoreElements = gmTiling->perCoreElements;
35	    t.lastCoreElements = gmTiling->lastCoreElements;
36	    t.perCoreLoops = gmTiling->perCoreLoops;
37	    t.lastCoreLoops = gmTiling->lastCoreLoops;
38	    t.perCorePerLoopElements = gmTiling->perCorePerLoopElements;
39	    t.lastCorePerLoopElements = gmTiling->lastCorePerLoopElements;
40	    t.perCoreLastLoopElements = gmTiling->perCoreLastLoopElements;
41	    t.lastCoreLastLoopElements = gmTiling->lastCoreLastLoopElements;
42	    t.oneLoopMaxElements = gmTiling->oneLoopMaxElements;
43	    t.sortNum = gmTiling->sortNum;
44	
45	    if (t.tilingMode == SORT_VALUES_MODE_FULLLOAD) {
46	        TPipe pipe;
47	        SortValuesFullLoad op;
48	        op.Init(input, output, &t, &pipe);
49	        op.Process();
50	    } else if (t.tilingMode == SORT_VALUES_MODE_MULTICORE) {
51	        TPipe pipe;
52	        SortValuesMultiCore op;
53	        op.Init(input, output, workspace, &t, &pipe);
54	        op.Process();
55	        pipe.Destroy();
56	    }
57	}
