3	 */
4	
5	#ifndef SORT_VALUES_FULLLOAD_H
6	#define SORT_VALUES_FULLLOAD_H
7	
8	#include "sort_values_common.h"
9	#include "sort_values_tiling.h"
10	
11	namespace SortValues {
12	using namespace AscendC;
13	
14	/// SortValuesFullLoad: single-row sort, entire row in UB.
15	/// Supports float32, float16, bfloat16; ascending/descending.
16	class SortValuesFullLoad
17	{
18	public:
19	    __aicore__ inline SortValuesFullLoad() {}
20	    __aicore__ inline void Init(
21	        GM_ADDR input, GM_ADDR output, const SortValuesTiling* tiling, TPipe* tPipe);
22	    __aicore__ inline void Process();
23	
24	private:
25	    __aicore__ inline void ProcessOneRow(int64_t row);
26	
27	protected:
28	    TPipe* pipe;
29	    TQue<QuePosition::VECIN, 1> copyInQueue;
30	    TQue<QuePosition::VECOUT, 1> copyOutQueue;
31	    TBuf<TPosition::VECCALC> calcBuf;
32	    TBuf<TPosition::VECCALC> sortBuf;
33	
34	    GlobalTensor<float> inputGmFloat;
35	    GlobalTensor<half>  inputGmHalf;
36	    GlobalTensor<float> outputGmFloat;
37	    GlobalTensor<half>  outputGmHalf;
38	
39	    int64_t totalRows, sortLen, sortNum;
40	    int32_t dtype, descending;
41	    int64_t blockIdx, coreNum, tasksPerCore;
42	    int64_t itemSize;
43	};
44	
45	__aicore__ inline void SortValuesFullLoad::Init(
46	    GM_ADDR input, GM_ADDR output, const SortValuesTiling* tiling, TPipe* tPipe)
47	{
48	    this->pipe = tPipe;
49	    this->totalRows = tiling->totalRows; this->sortLen = tiling->sortLen;
50	    this->sortNum = tiling->sortNum;
51	    this->dtype = tiling->dtype; this->descending = tiling->descending;
52	    this->blockIdx = GetBlockIdx(); this->coreNum = tiling->coreNum;
53	    this->tasksPerCore = CeilDiv(this->totalRows, this->coreNum);
54	    this->itemSize = (this->dtype == 0) ? sizeof(float) : sizeof(half);
55	
56	    inputGmFloat.SetGlobalBuffer((__gm__ float*)input, this->totalRows * this->sortLen);
57	    inputGmHalf.SetGlobalBuffer((__gm__ half*)input, this->totalRows * this->sortLen);
58	    outputGmFloat.SetGlobalBuffer((__gm__ float*)output, this->totalRows * this->sortLen);
59	    outputGmHalf.SetGlobalBuffer((__gm__ half*)output, this->totalRows * this->sortLen);
60	
61	    // Safe buffer: sortNum*(float+value)*2 + workspace. Use extra margin.
62	    // sortNum * sizeof(float) = base element. We need: input buffer (1x),
63	    // concat temp (2x), sort work (2x), sort output (4x), extract (2x).
64	    // Total: ~12x base. Use 16x for safety.
65	    int64_t bufBytes = this->sortNum * sizeof(float) * 16;
66	    pipe->InitBuffer(copyInQueue, 1, bufBytes);
67	    pipe->InitBuffer(copyOutQueue, 1, bufBytes);
68	    pipe->InitBuffer(calcBuf, bufBytes);
69	    pipe->InitBuffer(sortBuf, bufBytes);
70	}
71	
72	__aicore__ inline void SortValuesFullLoad::ProcessOneRow(int64_t row)
73	{
74	    int64_t rowOff = row * this->sortLen;
75	
76	    // ===== CopyIn =====
77	    LocalTensor<int8_t> inLocal = copyInQueue.AllocTensor<int8_t>();
78	    DataCopyExtParams inDp{1, static_cast<uint32_t>(this->sortLen * this->itemSize), 0, 0, 0};
79	    if (this->dtype == 0) {
80	        DataCopyPadExtParams<float> pp{false, 0, 0, 0};
81	        DataCopyPad(inLocal.ReinterpretCast<float>(), inputGmFloat[rowOff], inDp, pp);
82	    } else {
83	        DataCopyPadExtParams<half> pp{false, 0, 0, 0};
84	        DataCopyPad(inLocal.ReinterpretCast<half>(), inputGmHalf[rowOff], inDp, pp);
85	    }
86	    copyInQueue.EnQue(inLocal);
87	
88	    // ===== Compute =====
89	    inLocal = copyInQueue.DeQue<int8_t>();
90	
91	    // Step 1: Cast to float32
92	    LocalTensor<float> keysFp32;
93	    if (this->dtype == 0) {
94	        keysFp32 = inLocal.ReinterpretCast<float>();
95	    } else {
96	        LocalTensor<half> halfKeys = inLocal.ReinterpretCast<half>();
97	        keysFp32 = sortBuf.Get<float>(this->sortNum);
98	        Cast(keysFp32, halfKeys, RoundMode::CAST_NONE, this->sortLen);
99	    }
100	
101	    // Step 2: Negate if ascending
102	    if (this->descending == 0) {
103	        Muls(keysFp32, keysFp32, -1.0f, this->sortLen);
104	    }
105	
106	    // Step 3: Pad tail
107	    int64_t dupNum = this->sortLen % ONE_REPEAT_SORT_NUM;
108	    if (dupNum > 0) {
109	        uint64_t mask0 = UINT64_MAX;
110	        mask0 = mask0 << dupNum;
111	        mask0 = mask0 & (UINT64_MAX >> ONE_REPEAT_SORT_NUM);
112	        uint64_t mask[2] = {mask0, 0};
113	        Duplicate(keysFp32[this->sortLen - dupNum], MIN_FP32, mask,
114	            DST_BLK_STRIDE, DST_REP_STRIDE, 1);
115	    }
116	
117	    // Step 4: Dummy values for Sort (all zeros)
118	    LocalTensor<uint32_t> dummyVals = inLocal[this->sortNum].ReinterpretCast<uint32_t>();
119	    Duplicate(dummyVals, (uint32_t)0, this->sortNum);
120	
121	    // Step 5: Concat into sort format
122	    int64_t sortSize = GetSortLen<float>(this->sortNum);
123	    LocalTensor<float> concatTemp = calcBuf.Get<float>(sortSize);
124	    LocalTensor<float> concatLocal;
125	    Concat(concatLocal, keysFp32, concatTemp, this->sortNum / ONE_REPEAT_SORT_NUM);
126	
127	    // Step 6: Hardware Sort (descending float32)
128	    LocalTensor<float> sortResult = sortBuf.Get<float>(sortSize);
129	    LocalTensor<float> sortWork = calcBuf.Get<float>(sortSize * 2);
130	    Sort<float, true>(sortResult, concatLocal, dummyVals, sortWork, this->sortNum / ONE_REPEAT_SORT_NUM);
131	
132	    // Step 7: Extract sorted keys
133	    LocalTensor<float> outLocal = copyOutQueue.AllocTensor<float>();
134	    LocalTensor<float> sortedKeys = outLocal;
135	    LocalTensor<uint32_t> sortedDummy = outLocal[this->sortNum].ReinterpretCast<uint32_t>();
136	    Extract(sortedKeys, sortedDummy, sortResult, this->sortNum / ONE_REPEAT_SORT_NUM);
137	
138	    // Step 8: Un-negate if ascending
139	    if (this->descending == 0) {
140	        Muls(sortedKeys, sortedKeys, -1.0f, this->sortLen);
141	    }
142	
143	    copyInQueue.FreeTensor(inLocal);
144	
145	    // Step 9: Cast to output dtype, enqueue
146	    if (this->dtype != 0) {
147	        LocalTensor<half> outHalf = outLocal.ReinterpretCast<half>();
148	        Cast(outHalf, sortedKeys, RoundMode::CAST_ROUND, this->sortLen);
149	        copyOutQueue.EnQue<half>(outHalf);
150	    } else {
151	        copyOutQueue.EnQue<float>(outLocal);
152	    }
153	
154	    // ===== CopyOut =====
155	    DataCopyParams outDp{1, static_cast<uint16_t>(this->sortLen * this->itemSize), 0, 0};
156	    if (this->dtype == 0) {
157	        LocalTensor<float> out = copyOutQueue.DeQue<float>();
158	        DataCopyPad(outputGmFloat[rowOff], out, outDp);
159	        copyOutQueue.FreeTensor(out);
160	    } else {
161	        LocalTensor<half> out = copyOutQueue.DeQue<half>();
162	        DataCopyPad(outputGmHalf[rowOff], out, outDp);
163	        copyOutQueue.FreeTensor(out);
164	    }
165	}
