__aicore__ inline int64_t AlignUp32(int64_t n) {
    return ((n + 31) / 32) * 32;
}

__aicore__ inline int64_t SortEleNum(int64_t count) {
    // Sort requires element count to be multiple of ONE_REPEAT (32)
    return AlignUp32(count);
