 */

#include "kernel_operator.h"
#include "nms_tiling.h"
#include "nms_common.h"

using namespace AscendC;
using namespace NmsUtils;

class KernelNMS {
public:
    __aicore__ inline KernelNMS() {}
    __aicore__ inline void Init(
        GM_ADDR boxesGm, GM_ADDR scoresGm,
        GM_ADDR selectedIndicesGm, GM_ADDR numSelectedGm,
        GM_ADDR workspace, const NmsTiling* tiling, TPipe* tPipe);
    __aicore__ inline void Process();

private:
    __aicore__ inline void FilterAndSort();
    __aicore__ inline void ComputeAreas();
    __aicore__ inline void GreedyNMS();

    TPipe* pipe;

    // GM tensors
    GlobalTensor<float> boxesGmF32;
    GlobalTensor<half>  boxesGmF16;
    GlobalTensor<float> scoresGmF32;
    GlobalTensor<half>  scoresGmF16;

    // Workspace GM tensors (sorted results stored here)
    __gm__ float* wsSortedScores;   // [filteredN]
    __gm__ int32_t* wsSortedIndices; // [filteredN]
    __gm__ float* wsSortedBoxes;     // [filteredN, 4]
    __gm__ float* wsAreas;           // [filteredN]
    __gm__ uint8_t* wsSuppressed;    // [filteredN]

    // Output
    __gm__ int32_t* outSelectedIndices;
    __gm__ int32_t* outNumSelected;

    // Tiling parameters
    int32_t totalN, maxOutputSize, dtypeCode;
    int32_t blockN, paddedN;
    float iouThreshold, scoresThreshold;

    // UB queues
    TQue<QuePosition::VECIN, 1> copyInQ;
    TQue<QuePosition::VECOUT, 1> copyOutQ;
    TBuf<TPosition::VECCALC> calcBuf;
    TBuf<TPosition::VECCALC> sortBuf;
    TBuf<TPosition::VECCALC> tmpBuf;

    int64_t itemSize;
    int64_t filteredTotal;
    int64_t sortEleNum;
    int64_t sortLen;
};

// ========================== Init ==========================

__aicore__ inline void KernelNMS::Init(
    GM_ADDR boxesGm, GM_ADDR scoresGm,
    GM_ADDR selectedIndicesGm, GM_ADDR numSelectedGm,
    GM_ADDR workspace, const NmsTiling* tiling, TPipe* tPipe)
{
    this->pipe = tPipe;
    this->totalN = tiling->totalN;
    this->maxOutputSize = tiling->maxOutputSize;
    this->dtypeCode = tiling->dtypeCode;
    this->blockN = tiling->blockN;
    this->paddedN = tiling->paddedN;
    this->iouThreshold = tiling->iouThreshold;
    this->scoresThreshold = tiling->scoresThreshold;
    this->itemSize = (this->dtypeCode == 0) ? sizeof(float) : sizeof(half);

    // Setup input GM tensors
    if (this->dtypeCode == 0) {
        boxesGmF32.SetGlobalBuffer((__gm__ float*)boxesGm, this->totalN * 4);
        scoresGmF32.SetGlobalBuffer((__gm__ float*)scoresGm, this->totalN);
    } else {
        boxesGmF16.SetGlobalBuffer((__gm__ half*)boxesGm, this->totalN * 4);
        scoresGmF16.SetGlobalBuffer((__gm__ half*)scoresGm, this->totalN);
    }

    // Workspace layout:
    //   [0, N) float:     sorted_scores
    //   [N, 2N) int32:    sorted_indices (original indices)
    //   [2N, 2N+N*4) float: sorted_boxes [x1,y1,x2,y2]
    //   [2N+N*4, 2N+N*5) float: areas
    //   [2N+N*5, 2N+N*5+N) uint8: suppressed flags
    __gm__ int8_t* ws = (__gm__ int8_t*)workspace;
    this->wsSortedScores = (__gm__ float*)(ws);
    this->wsSortedIndices = (__gm__ int32_t*)(ws + this->totalN * sizeof(float));
    this->wsSortedBoxes = (__gm__ float*)(ws + this->totalN * sizeof(float) + this->totalN * sizeof(int32_t));
    this->wsAreas = (__gm__ float*)(ws + this->totalN * sizeof(float) + this->totalN * sizeof(int32_t) + this->totalN * 4 * sizeof(float));
    this->wsSuppressed = (__gm__ uint8_t*)(ws + this->totalN * sizeof(float) + this->totalN * sizeof(int32_t) + this->totalN * 4 * sizeof(float) + this->totalN * sizeof(float));

    // Output
    this->outSelectedIndices = (__gm__ int32_t*)selectedIndicesGm;
    this->outNumSelected = (__gm__ int32_t*)numSelectedGm;

    // Init UB buffers
    // sortEleNum: padding to 32-aligned for Sort
    this->sortEleNum = SortEleNum(this->blockN);
    this->sortLen = GetSortLen(this->sortEleNum);

    // UB budget: sortLen*sizeof(float) for keys
    //   + sortEleNum*sizeof(uint32_t) for dummy vals
    //   + additional for sort work, concat temp, boxes, etc.
    // Total: ~sortEleNum * 24 bytes (safe estimate)
    int64_t bufBytes = this->sortEleNum * sizeof(float) * 24;
    pipe->InitBuffer(copyInQ, 1, bufBytes);
    pipe->InitBuffer(copyOutQ, 1, bufBytes);
    pipe->InitBuffer(calcBuf, bufBytes);
    pipe->InitBuffer(sortBuf, bufBytes);
    pipe->InitBuffer(tmpBuf, bufBytes);

    this->filteredTotal = 0;
}

// ========================== Process ==========================

__aicore__ inline void KernelNMS::Process()
{
    if (GetBlockIdx() != 0) {
        return;  // Only core 0 does the work in single-core mode
    }

    // Phase 1: Filter by score threshold and sort descending
    FilterAndSort();

    if (this->filteredTotal == 0) {
        // No boxes pass threshold
        *(this->outNumSelected) = 0;
        return;
    }

    // Phase 2: Compute areas
    ComputeAreas();

    // Phase 3: Greedy NMS loop
    GreedyNMS();
}

// ========================== Phase 1: FilterAndSort ==========================

__aicore__ inline void KernelNMS::FilterAndSort()
{
    int64_t totalTiles = CeilDiv(this->totalN, this->blockN);
    this->filteredTotal = 0;

    for (int64_t tileIdx = 0; tileIdx < totalTiles; tileIdx++) {
        int64_t offset = tileIdx * this->blockN;
        int64_t curN = MinVal<int64_t>(this->blockN, this->totalN - offset);
        int64_t curSortNum = SortEleNum(curN);
        int64_t curSortLen = GetSortLen(curSortNum);

        // --- CopyIn: load scores and boxes ---
        LocalTensor<int8_t> inLocal = copyInQ.AllocTensor<int8_t>();

        // Load scores
        DataCopyExtParams scoreDp{1, static_cast<uint32_t>(curN * this->itemSize), 0, 0, 0};
        if (this->dtypeCode == 0) {
            DataCopyPadExtParams<float> pp{false, 0, 0, 0};
            DataCopyPad(inLocal.ReinterpretCast<float>(), scoresGmF32[offset], scoreDp, pp);
        } else {
            DataCopyPadExtParams<half> pp{false, 0, 0, 0};
            DataCopyPad(inLocal.ReinterpretCast<half>(), scoresGmF16[offset], scoreDp, pp);
        }
        copyInQ.EnQue(inLocal);
        inLocal = copyInQ.DeQue<int8_t>();

        // Cast scores to float32
        LocalTensor<float> scoresF32;
        if (this->dtypeCode == 0) {
            scoresF32 = inLocal.ReinterpretCast<float>();
        } else {
            LocalTensor<half> scoresF16 = inLocal.ReinterpretCast<half>();
            scoresF32 = calcBuf.Get<float>(curSortNum);
            Cast(scoresF32, scoresF16, RoundMode::CAST_NONE, curN);
        }

        // --- Filter: check scores > threshold, compact into sort format ---
        // Step 1: Negate scores for descending sort (Sort is ascending by default... actually Sort<float,true> is descending)
        // We'll use Sort<float, true> for descending directly

        // Step 2: Pad tail for Sort alignment
        int64_t dupNum = curN % NMS_ONE_REPEAT;
        if (dupNum > 0) {
            uint64_t mask0 = UINT64_MAX;
            mask0 = mask0 << dupNum;
            mask0 = mask0 & (UINT64_MAX >> NMS_ONE_REPEAT);
            uint64_t mask[2] = {mask0, 0};
            Duplicate(scoresF32[curN - dupNum], NMS_MIN_FP32, mask, 1, 8, 1);
        }

        // Step 3: Create index vector [offset, offset+1, ..., offset+curN-1]
        LocalTensor<int32_t> indexBuf = inLocal[curSortNum].ReinterpretCast<int32_t>();
        Duplicate(indexBuf, (int32_t)0, curSortNum);

        // Create arithmetic progression for indices
        LocalTensor<float> indexF32 = calcBuf.Get<float>(curSortNum);
        LocalTensor<int32_t> idxTmp = tmpBuf.Get<int32_t>(curSortNum);
        LocalTensor<float> idxTmpF32 = idxTmp.ReinterpretCast<float>();

        // Set up index values: we'll build them with a loop since ArithProgression
        // requires specific alignment. Use scalar loop for correctness.
        // For each position, store original global index.
        // We'll store indices during the sort preparation phase.

        // Actually, let me build the sort records differently.
        // Each sort record = [score_float32, dummy_uint32]
        // We'll use the dummy field to encode the original index.
        LocalTensor<uint32_t> dummyVals = inLocal[curSortNum].ReinterpretCast<uint32_t>();

        // Fill dummy values with original indices (cast to uint32)
        for (int64_t i = 0; i < curN; i++) {
            dummyVals.SetValue(i, static_cast<uint32_t>(offset + i));
        }

        // Step 4: Concat into sort format
        LocalTensor<float> concatTemp = tmpBuf.Get<float>(curSortLen);
        LocalTensor<float> concatLocal;
        Concat(concatLocal, scoresF32, concatTemp, curSortNum / NMS_ONE_REPEAT);

        // Step 5: Sort (descending)
        LocalTensor<float> sortResult = sortBuf.Get<float>(curSortLen);
        LocalTensor<float> sortWork = calcBuf.Get<float>(curSortLen * 2);
        Sort<float, true>(sortResult, concatLocal, dummyVals, sortWork, curSortNum / NMS_ONE_REPEAT);

        // Step 6: Extract sorted keys and indices
        LocalTensor<float> sortedKeys = copyOutQ.AllocTensor<float>();
        LocalTensor<uint32_t> sortedIndices = sortedKeys[curSortNum].ReinterpretCast<uint32_t>();
        Extract(sortedKeys, sortedIndices, sortResult, curSortNum / NMS_ONE_REPEAT);

        // Free input buffer
        copyInQ.FreeTensor(inLocal);

        // Step 7: Filter sorted results by score threshold and write to workspace
        // Now we need to write only boxes with score > scoresThreshold
        // We iterate through sorted results and write passing boxes to workspace

        // Load boxes for this tile into calcBuf
        LocalTensor<float> boxesF32 = calcBuf.Get<float>(curSortNum * 4);
        // Load boxes from GM
        for (int64_t i = 0; i < curN; i++) {
            int64_t origIdx = static_cast<int64_t>(sortedIndices.GetValue(i));
            if (origIdx >= this->totalN) continue; // safety check

            float score = sortedKeys.GetValue(i);
            if (score <= this->scoresThreshold) continue;

            // Load box from GM
            float x1, y1, x2, y2;
            if (this->dtypeCode == 0) {
                x1 = boxesGmF32.GetValue(origIdx * 4 + 0);
                y1 = boxesGmF32.GetValue(origIdx * 4 + 1);
                x2 = boxesGmF32.GetValue(origIdx * 4 + 2);
                y2 = boxesGmF32.GetValue(origIdx * 4 + 3);
            } else {
                x1 = (float)boxesGmF16.GetValue(origIdx * 4 + 0);
                y1 = (float)boxesGmF16.GetValue(origIdx * 4 + 1);
                x2 = (float)boxesGmF16.GetValue(origIdx * 4 + 2);
                y2 = (float)boxesGmF16.GetValue(origIdx * 4 + 3);
            }

            int64_t pos = this->filteredTotal;
            if (pos >= this->totalN) break;

            wsSortedScores[pos] = score;
            wsSortedIndices[pos] = (int32_t)origIdx;
            wsSortedBoxes[pos * 4 + 0] = x1;
            wsSortedBoxes[pos * 4 + 1] = y1;
            wsSortedBoxes[pos * 4 + 2] = x2;
            wsSortedBoxes[pos * 4 + 3] = y2;

            this->filteredTotal++;
        }

        copyOutQ.FreeTensor(sortedKeys);
    }

    // Sort passes through the workspace data in multiple passes
    // Since each tile was processed independently, we need to sort the full filtered result.
    // For tiles > 1, do additional sort passes.
    if (totalTiles > 1 && this->filteredTotal > 1) {
        // Load filtered data in tiles, sort each tile, write back
        // Use a simple bubble/tile sort across workspace
        // For simplicity in first implementation: re-sort the workspace
        int64_t totalFilterTiles = CeilDiv(this->filteredTotal, this->blockN);

        for (int64_t pass = 0; pass < totalFilterTiles; pass++) {
            for (int64_t tileA = 0; tileA < totalFilterTiles - 1; tileA++) {
                for (int64_t tileB = tileA + 1; tileB < totalFilterTiles; tileB++) {
                    // Compare min score of tileA with max score of tileB
                    int64_t startA = tileA * this->blockN;
                    int64_t endA = MinVal<int64_t>(startA + this->blockN, this->filteredTotal);
                    int64_t startB = tileB * this->blockN;
                    int64_t endB = MinVal<int64_t>(startB + this->blockN, this->filteredTotal);

                    float minA = wsSortedScores[endA - 1]; // last (smallest) in tileA
                    float maxB = wsSortedScores[startB];   // first (largest) in tileB

                    if (maxB > minA) {
                        // Need to merge and re-sort tiles A and B
                        int64_t mergeN = (endA - startA) + (endB - startB);
                        if (mergeN > this->blockN * 2) mergeN = this->blockN * 2;
                        int64_t mergeSortN = SortEleNum(mergeN);
                        int64_t mergeSortLen = GetSortLen(mergeSortN);

                        // Load into UB, sort, write back
                        LocalTensor<float> mergeKeys = calcBuf.Get<float>(mergeSortN);
                        LocalTensor<uint32_t> mergeIndices = calcBuf.Get<uint32_t>(mergeSortN + mergeSortN);

                        // Copy scores + indices as sort pairs
                        int64_t idx = 0;
                        // Copy from tileA
                        for (int64_t i = startA; i < endA && idx < this->blockN; i++) {
                            mergeKeys.SetValue(idx, wsSortedScores[i]);
                            mergeIndices.SetValue(idx, (uint32_t)wsSortedIndices[i]);
                            idx++;
                        }
                        // Copy from tileB
                        for (int64_t i = startB; i < endB && idx < mergeN; i++) {
                            mergeKeys.SetValue(idx, wsSortedScores[i]);
                            mergeIndices.SetValue(idx, (uint32_t)wsSortedIndices[i]);
                            idx++;
                        }

                        // Pad tail
                        int64_t dupN = mergeN % NMS_ONE_REPEAT;
                        if (dupN > 0) {
                            uint64_t mask0 = UINT64_MAX;
                            mask0 = mask0 << dupN;
                            mask0 = mask0 & (UINT64_MAX >> NMS_ONE_REPEAT);
                            uint64_t mask[2] = {mask0, 0};
                            Duplicate(mergeKeys[mergeN - dupN], NMS_MIN_FP32, mask, 1, 8, 1);
                        }

                        // Concat + Sort + Extract
                        LocalTensor<float> concatTmp = sortBuf.Get<float>(mergeSortLen);
                        LocalTensor<float> concatMerged;
                        Concat(concatMerged, mergeKeys, concatTmp, mergeSortN / NMS_ONE_REPEAT);

                        LocalTensor<float> sortRes = tmpBuf.Get<float>(mergeSortLen);
                        LocalTensor<float> sortWk = sortBuf.Get<float>(mergeSortLen * 2);
                        Sort<float, true>(sortRes, concatMerged, mergeIndices, sortWk, mergeSortN / NMS_ONE_REPEAT);

                        LocalTensor<float> extractedK = concatMerged; // reuse buffer
                        LocalTensor<uint32_t> extractedI = extractedK[mergeSortN].ReinterpretCast<uint32_t>();
                        Extract(extractedK, extractedI, sortRes, mergeSortN / NMS_ONE_REPEAT);

                        // Write back sorted result
                        for (int64_t i = 0; i < mergeN; i++) {
                            int64_t pos = startA + i;
                            float score = extractedK.GetValue(i);
                            int32_t origIdx = (int32_t)extractedI.GetValue(i);

                            // Swap with workspace: we need to also swap box data
                            // For simplicity, store back to temporary and then swap
                            // This re-sorts both tiles A and B
                            if (pos < this->totalN) {
                                wsSortedScores[pos] = score;
                                wsSortedIndices[pos] = origIdx;
                            }
                        }
                    }
                }
            }
        }
    }
}

// ========================== Phase 2: ComputeAreas ==========================

__aicore__ inline void KernelNMS::ComputeAreas()
{
    for (int64_t i = 0; i < this->filteredTotal; i++) {
        float x1 = wsSortedBoxes[i * 4 + 0];
        float y1 = wsSortedBoxes[i * 4 + 1];
        float x2 = wsSortedBoxes[i * 4 + 2];
        float y2 = wsSortedBoxes[i * 4 + 3];
        float area = (x2 - x1) * (y2 - y1);
        wsAreas[i] = area;
        wsSuppressed[i] = 0;
    }
}

// ========================== Phase 3: GreedyNMS ==========================

__aicore__ inline void KernelNMS::GreedyNMS()
{
    int64_t selectedCount = 0;
    int64_t iouTileN = this->blockN;

    // UB buffers for IoU computation (in tiles)
    // Box coordinates
    LocalTensor<float> candX1 = tmpBuf.Get<float>(iouTileN);
    LocalTensor<float> candY1 = tmpBuf.Get<float>(iouTileN + iouTileN);
    LocalTensor<float> candX2 = tmpBuf.Get<float>(iouTileN + iouTileN * 2);
    LocalTensor<float> candY2 = tmpBuf.Get<float>(iouTileN + iouTileN * 3);
    LocalTensor<float> candAreas = tmpBuf.Get<float>(iouTileN + iouTileN * 4);
    LocalTensor<uint8_t> candSuppress = tmpBuf.Get<uint8_t>(iouTileN + iouTileN * 5);

    // Intermediate buffers
    LocalTensor<float> interX1 = sortBuf.Get<float>(iouTileN);
    LocalTensor<float> interY1 = sortBuf.Get<float>(iouTileN + iouTileN);
    LocalTensor<float> interX2 = sortBuf.Get<float>(iouTileN + iouTileN * 2);
    LocalTensor<float> interY2 = sortBuf.Get<float>(iouTileN + iouTileN * 3);
    LocalTensor<float> interW = sortBuf.Get<float>(iouTileN + iouTileN * 4);
    LocalTensor<float> interH = sortBuf.Get<float>(iouTileN + iouTileN * 5);
    LocalTensor<float> interArea = sortBuf.Get<float>(iouTileN + iouTileN * 6);
    LocalTensor<float> unionArea = sortBuf.Get<float>(iouTileN + iouTileN * 7);
    LocalTensor<float> iouVal = sortBuf.Get<float>(iouTileN + iouTileN * 8);
    LocalTensor<uint16_t> iouMask = sortBuf.Get<uint16_t>(iouTileN + iouTileN * 9);

    // Zero buffer for clamping
    LocalTensor<float> zeroBuf = calcBuf.Get<float>(iouTileN);
    Duplicate(zeroBuf, 0.0f, iouTileN);

    // Epsilon buffer
    LocalTensor<float> epsBuf = calcBuf.Get<float>(iouTileN + iouTileN);
    Duplicate(epsBuf, 1e-6f, iouTileN);

    // Main greedy loop
    for (int64_t i = 0; i < this->filteredTotal && selectedCount < this->maxOutputSize; i++) {
        if (wsSuppressed[i] != 0) continue;

        // Select box i
        outSelectedIndices[selectedCount] = wsSortedIndices[i];
        selectedCount++;

        float curX1 = wsSortedBoxes[i * 4 + 0];
        float curY1 = wsSortedBoxes[i * 4 + 1];
        float curX2 = wsSortedBoxes[i * 4 + 2];
        float curY2 = wsSortedBoxes[i * 4 + 3];
        float curArea = wsAreas[i];

        // Process remaining boxes in tiles
        for (int64_t tileStart = i + 1; tileStart < this->filteredTotal; tileStart += iouTileN) {
            int64_t tileEnd = MinVal<int64_t>(tileStart + iouTileN, this->filteredTotal);
            int64_t tileLen = tileEnd - tileStart;

            // Load candidate data: boxes, areas, suppressed flags
            for (int64_t j = 0; j < tileLen; j++) {
                int64_t idx = tileStart + j;
                candX1.SetValue(j, wsSortedBoxes[idx * 4 + 0]);
                candY1.SetValue(j, wsSortedBoxes[idx * 4 + 1]);
                candX2.SetValue(j, wsSortedBoxes[idx * 4 + 2]);
                candY2.SetValue(j, wsSortedBoxes[idx * 4 + 3]);
                candAreas.SetValue(j, wsAreas[idx]);
                candSuppress.SetValue(j, wsSuppressed[idx]);
            }

            // Compute IoU using vector operations
            // x1_inter = max(cur_x1, cand_x1)
            Maxs(interX1, candX1, curX1, tileLen);
            // y1_inter = max(cur_y1, cand_y1)
            Maxs(interY1, candY1, curY1, tileLen);
            // x2_inter = min(cur_x2, cand_x2)
            Mins(interX2, candX2, curX2, tileLen);
            // y2_inter = min(cur_y2, cand_y2)
            Mins(interY2, candY2, curY2, tileLen);

            // inter_w = x2_inter - x1_inter
            Sub(interW, interX2, interX1, tileLen);
            // inter_h = y2_inter - y1_inter
            Sub(interH, interY2, interY1, tileLen);

            // clamp to >= 0 using Relu
            Relu(interW, interW, tileLen);
            Relu(interH, interH, tileLen);

            // inter_area = inter_w * inter_h
            Mul(interArea, interW, interH, tileLen);

            // union_area = cur_area + cand_areas - inter_area
            Adds(unionArea, candAreas, curArea, tileLen);
            Sub(unionArea, unionArea, interArea, tileLen);

            // union_area = max(union_area, 1e-6) to avoid div by zero
            Max(unionArea, unionArea, epsBuf, tileLen);

            // iou = inter_area / union_area
            Div(iouVal, interArea, unionArea, tileLen);

            // mask = iou >= iou_threshold
            Compare(iouMask, iouVal, this->iouThreshold, CMPMODE::GE, tileLen);

            // Update suppression flags
            for (int64_t j = 0; j < tileLen; j++) {
                int64_t idx = tileStart + j;
                if (candSuppress.GetValue(j) != 0) continue; // already suppressed
                uint16_t maskVal = iouMask.GetValue(j);
                if (maskVal != 0) {
                    wsSuppressed[idx] = 1;
                }
            }
        }
    }

    *(this->outNumSelected) = static_cast<int32_t>(selectedCount);
}

// ========================== Kernel Entry ==========================

extern "C" __global__ __aicore__ void nms_kernel(
    GM_ADDR boxes, GM_ADDR scores,
    GM_ADDR selected_indices, GM_ADDR num_selected,
    GM_ADDR workspace, GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIV_1_0);
    if (g_coreType == AIC) {
        return;
    }

    auto* gmTiling = reinterpret_cast<__gm__ NmsTiling*>(tiling);
    NmsTiling t;
    t.totalN = gmTiling->totalN;
    t.maxOutputSize = gmTiling->maxOutputSize;
    t.dtypeCode = gmTiling->dtypeCode;
    t.totalCores = gmTiling->totalCores;
    t.blockN = gmTiling->blockN;
    t.tileN = gmTiling->tileN;
    t.paddedN = gmTiling->paddedN;
    t.filteredN = gmTiling->filteredN;
    t.iouThreshold = gmTiling->iouThreshold;
    t.scoresThreshold = gmTiling->scoresThreshold;
    t.padOutputSize = gmTiling->padOutputSize;

    TPipe pipe;
    KernelNMS op;
    op.Init(boxes, scores, selected_indices, num_selected, workspace, &t, &pipe);
    op.Process();
    pipe.Destroy();
}
