#include "nms_tiling.h"

namespace ascend_kernel {

static int32_t getDtypeCode(at::ScalarType dtype)
{
    if (dtype == at::kFloat)    return 0;
    if (dtype == at::kHalf)     return 1;
    if (dtype == at::kBFloat16) return 2;
    TORCH_CHECK(false, "NMS: unsupported dtype, expected float32/float16/bfloat16");
    return -1;
}

std::tuple<at::Tensor, at::Tensor> nms(
    const at::Tensor& boxes,
    const at::Tensor& scores,
    int64_t max_output_size,
    double iou_threshold,
    double scores_threshold,
    bool pad_to_max_output_size)
{
    // Input validation
    TORCH_CHECK(boxes.dim() == 2 && boxes.size(1) == 4,
                "boxes must have shape [N, 4]");
    TORCH_CHECK(scores.dim() == 1 && scores.size(0) == boxes.size(0),
                "scores must have shape [N] matching boxes");
    TORCH_CHECK(boxes.is_contiguous(), "boxes must be contiguous");
    TORCH_CHECK(scores.is_contiguous(), "scores must be contiguous");

    auto dtype = boxes.scalar_type();
    TORCH_CHECK(dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16,
                "NMS supports float32, float16, bfloat16");
    TORCH_CHECK(scores.scalar_type() == dtype,
                "boxes and scores must have same dtype");

    int32_t totalN = static_cast<int32_t>(boxes.size(0));
    int32_t maxOut = static_cast<int32_t>(max_output_size);

    // Output tensors
    auto options = boxes.options();
    auto selectedIndices = at::zeros({max_out}, options.dtype(at::kInt));
    auto numSelected = at::zeros({1}, options.dtype(at::kInt));

    // Platform info
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t totalCores = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize = 0;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Compute tiling
    int32_t dtypeCode = getDtypeCode(dtype);
    int32_t blockN = static_cast<int32_t>(NMS_BLOCK_N);

    // Prepare tiling
    at::Tensor tilingCpu = at::empty(
        {static_cast<int64_t>(sizeof(NmsTiling))},
        at::device(at::kCPU).dtype(at::kByte));
    auto* t = reinterpret_cast<NmsTiling*>(tilingCpu.data_ptr());

    t->totalN = totalN;
    t->maxOutputSize = maxOut;
    t->dtypeCode = dtypeCode;
    t->totalCores = static_cast<int32_t>(totalCores);
    t->blockN = blockN;
    t->tileN = blockN;
    t->paddedN = ((totalN + NMS_BLOCK_BYTES - 1) / NMS_BLOCK_BYTES) * NMS_BLOCK_BYTES / sizeof(float);
    t->filteredN = 0;
    t->iouThreshold = static_cast<float>(iou_threshold);
    t->scoresThreshold = static_cast<float>(scores_threshold);
    t->padOutputSize = pad_to_max_output_size ? 1 : 0;

    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    // Workspace allocation
    // Layout:
    //   sorted_scores: [N] float   = N * 4 bytes
    //   sorted_indices: [N] int32  = N * 4 bytes
    //   sorted_boxes: [N, 4] float = N * 16 bytes
    //   areas: [N] float           = N * 4 bytes
    //   suppressed: [N] uint8      = N * 1 byte
    int64_t wsBytes = static_cast<int64_t>(totalN) * (4 + 4 + 16 + 4 + 1) + 4096;
    at::Tensor workspace = at::empty({wsBytes}, options.dtype(at::kByte));

    // Launch kernel
    uint32_t blockDim = 1; // Single core for NMS greedy loop
    int64_t totalLen = static_cast<int64_t>(totalN);

    EXEC_KERNEL_CMD(nms_kernel, blockDim,
        boxes, scores, selectedIndices, numSelected,
        workspace, tilingNpu);

    return std::make_tuple(selectedIndices, numSelected);
}

} // namespace ascend_kernel
