/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * NMS (Non-Maximum Suppression) - Single Core Implementation
 *
 * Algorithm:
 *   Phase 1: Load all boxes/scores from GM, filter by score threshold,
 *            store passing boxes in workspace, track original indices.
 *   Phase 2: Compute box areas.
 *   Phase 3: Greedy loop - at each step, find highest-score unsuppressed
 *            box, add to output, then suppress all boxes with IoU >= threshold.
 */

#include "kernel_operator.h"
#include "nms_tiling.h"

using namespace AscendC;

class KernelNMS {
public:
    __aicore__ inline KernelNMS() {}
    __aicore__ inline void Init(GM_ADDR boxes, GM_ADDR scores,
        GM_ADDR selectedIdx, GM_ADDR numSel, GM_ADDR ws, const NmsTiling* t, TPipe* p);
    __aicore__ inline void Process();

private:
    __aicore__ inline void Phase1_Filter();
    __aicore__ inline void Phase2_Areas();
    __aicore__ inline void Phase3_GreedyLoop();

    TPipe* pipe_;
    TQue<QuePosition::VECIN, 1> qi_;
    TQue<QuePosition::VECOUT, 1> qo_;
    TBuf<TPosition::VECCALC> cb_;
    TBuf<TPosition::VECCALC> sb_;

    GlobalTensor<float> boxesGmF32_;
    GlobalTensor<half>  boxesGmF16_;
    GlobalTensor<float> scoresGmF32_;
    GlobalTensor<half>  scoresGmF16_;

    __gm__ float* wsBoxes_;      // [filteredN, 4]
    __gm__ float* wsScores_;     // [filteredN]
    __gm__ int32_t* wsIndices_;  // [filteredN] original indices
    __gm__ float* wsAreas_;      // [filteredN]
    __gm__ uint8_t* wsSuppress_; // [filteredN]

    __gm__ int32_t* outIdx_;
    __gm__ int32_t* outNum_;

    int32_t N_, maxOut_, dc_;
    int32_t blockN_;
    float iouTh_, scoreTh_;
    int64_t isize_;
    int64_t filteredTotal_;
};

// Find index of max value in UB tensor using scalar scan
template<typename T>
__aicore__ inline int64_t ArgMax(const LocalTensor<T>& data, int64_t len) {
    T maxVal = data.GetValue(0);
    int64_t maxIdx = 0;
    for (int64_t i = 1; i < len; i++) {
        T val = data.GetValue(i);
        if (val > maxVal) {
            maxVal = val;
            maxIdx = i;
        }
    }
    return maxIdx;
}

__aicore__ inline void KernelNMS::Init(
    GM_ADDR boxes, GM_ADDR scores,
    GM_ADDR selectedIdx, GM_ADDR numSel,
    GM_ADDR ws, const NmsTiling* t, TPipe* p)
{
    pipe_ = p;
    N_ = t->totalN; maxOut_ = t->maxOutputSize;
    dc_ = t->dtypeCode; blockN_ = t->blockN;
    iouTh_ = t->iouThreshold; scoreTh_ = t->scoresThreshold;
    isize_ = (dc_ == 0) ? sizeof(float) : sizeof(half);

    if (dc_ == 0) {
        boxesGmF32_.SetGlobalBuffer((__gm__ float*)boxes, N_ * 4);
        scoresGmF32_.SetGlobalBuffer((__gm__ float*)scores, N_);
    } else {
        boxesGmF16_.SetGlobalBuffer((__gm__ half*)boxes, N_ * 4);
        scoresGmF16_.SetGlobalBuffer((__gm__ half*)scores, N_);
    }

    // Workspace layout:
    //   boxes:   ws[0 .. N*4*4-1]
    //   scores:  ws[N*4*4 .. N*4*4 + N*4-1]
    //   indices: ws[N*4*4 + N*4 .. N*4*4 + N*8-1]
    //   areas:   ws[N*4*4 + N*8 .. N*4*4 + N*12-1]
    //   supp:    ws[N*4*4 + N*12 .. N*4*4 + N*13-1]
    __gm__ int8_t* wb = (__gm__ int8_t*)ws;
    wsBoxes_ = (__gm__ float*)wb;
    wsScores_ = (__gm__ float*)(wb + N_ * 4 * sizeof(float));
    wsIndices_ = (__gm__ int32_t*)(wb + N_ * 8 * sizeof(float));
    wsAreas_ = (__gm__ float*)(wb + N_ * 8 * sizeof(float) + N_ * sizeof(int32_t));
    wsSuppress_ = (__gm__ uint8_t*)(wb + N_ * 8 * sizeof(float) + N_ * sizeof(int32_t) + N_ * sizeof(float));

    outIdx_ = (__gm__ int32_t*)selectedIdx;
    outNum_ = (__gm__ int32_t*)numSel;

    int64_t bufBytes = blockN_ * sizeof(float) * 12;
    pipe_->InitBuffer(qi_, 1, bufBytes);
    pipe_->InitBuffer(qo_, 1, bufBytes);
    pipe_->InitBuffer(cb_, bufBytes);
    pipe_->InitBuffer(sb_, bufBytes);

    filteredTotal_ = 0;
}

// ========================== Phase 1: Filter by score ==========================
// For each tile of input boxes:
//   1. Load scores into UB
//   2. Check score > threshold
//   3. If passes, load corresponding box and write to workspace
__aicore__ inline void KernelNMS::Phase1_Filter()
{
    int64_t tiles = (N_ + blockN_ - 1) / blockN_;

    for (int64_t ti = 0; ti < tiles; ti++) {
        int64_t off = ti * blockN_;
        int64_t cur = (off + blockN_ <= N_) ? blockN_ : (N_ - off);

        // Load scores
        LocalTensor<int8_t> inL = qi_.AllocTensor<int8_t>();
        DataCopyExtParams dp{1, static_cast<uint32_t>(cur * isize_), 0, 0, 0};
        if (dc_ == 0) {
            DataCopyPadExtParams<float> pp{false, 0, 0, 0};
            DataCopyPad(inL.ReinterpretCast<float>(), scoresGmF32_[off], dp, pp);
        } else {
            DataCopyPadExtParams<half> pp{false, 0, 0, 0};
            DataCopyPad(inL.ReinterpretCast<half>(), scoresGmF16_[off], dp, pp);
        }
        qi_.EnQue(inL);
        inL = qi_.DeQue<int8_t>();

        // Cast to float32
        LocalTensor<float> sf32;
        if (dc_ == 0) {
            sf32 = inL.ReinterpretCast<float>();
        } else {
            LocalTensor<half> s16 = inL.ReinterpretCast<half>();
            sf32 = cb_.Get<float>(blockN_);
            Cast(sf32, s16, RoundMode::CAST_NONE, cur);
        }

        // Filter: check each score against threshold
        for (int64_t i = 0; i < cur; i++) {
            float s = sf32.GetValue(i);
            if (s <= scoreTh_) continue;

            int64_t pos = filteredTotal_;
            if (pos >= N_) break;

            // Read box coordinates
            float x1, y1, x2, y2;
            if (dc_ == 0) {
                x1 = boxesGmF32_.GetValue((off + i) * 4 + 0);
                y1 = boxesGmF32_.GetValue((off + i) * 4 + 1);
                x2 = boxesGmF32_.GetValue((off + i) * 4 + 2);
                y2 = boxesGmF32_.GetValue((off + i) * 4 + 3);
            } else {
                x1 = static_cast<float>(boxesGmF16_.GetValue((off + i) * 4 + 0));
                y1 = static_cast<float>(boxesGmF16_.GetValue((off + i) * 4 + 1));
                x2 = static_cast<float>(boxesGmF16_.GetValue((off + i) * 4 + 2));
                y2 = static_cast<float>(boxesGmF16_.GetValue((off + i) * 4 + 3));
            }

            wsBoxes_[pos * 4 + 0] = x1;
            wsBoxes_[pos * 4 + 1] = y1;
            wsBoxes_[pos * 4 + 2] = x2;
            wsBoxes_[pos * 4 + 3] = y2;
            wsScores_[pos] = s;
            wsIndices_[pos] = static_cast<int32_t>(off + i);

            filteredTotal_++;
        }

        qi_.FreeTensor(inL);
    }
}

// ========================== Phase 2: Compute areas ==========================
__aicore__ inline void KernelNMS::Phase2_Areas()
{
    for (int64_t i = 0; i < filteredTotal_; i++) {
        float w = wsBoxes_[i * 4 + 2] - wsBoxes_[i * 4 + 0];
        float h = wsBoxes_[i * 4 + 3] - wsBoxes_[i * 4 + 1];
        wsAreas_[i] = w * h;
        wsSuppress_[i] = 0;
    }
}

// ========================== Phase 3: Greedy Loop ==========================
// At each iteration:
//   1. Scan all non-suppressed boxes to find max score
//   2. Select that box, add to output
//   3. For all non-suppressed remaining boxes, compute IoU, suppress if >= threshold
__aicore__ inline void KernelNMS::Phase3_GreedyLoop()
{
    int64_t selCount = 0;
    int64_t iouTileN = blockN_;

    for (int64_t iter = 0; iter < filteredTotal_ && selCount < maxOut_; iter++) {
        // Step 1: Find max score among non-suppressed boxes
        float bestScore = -1.0f;
        int64_t bestIdx = -1;

        for (int64_t i = 0; i < filteredTotal_; i++) {
            if (wsSuppress_[i] != 0) continue;
            float s = wsScores_[i];
            if (s > bestScore) {
                bestScore = s;
                bestIdx = i;
            }
        }

        if (bestIdx < 0 || bestScore <= scoreTh_) break;

        // Step 2: Select this box
        outIdx_[selCount] = wsIndices_[bestIdx];
        selCount++;
        wsSuppress_[bestIdx] = 1; // mark as processed

        float curX1 = wsBoxes_[bestIdx * 4 + 0];
        float curY1 = wsBoxes_[bestIdx * 4 + 1];
        float curX2 = wsBoxes_[bestIdx * 4 + 2];
        float curY2 = wsBoxes_[bestIdx * 4 + 3];
        float curArea = wsAreas_[bestIdx];

        // Step 3: Suppress overlapping boxes
        for (int64_t j = 0; j < filteredTotal_; j++) {
            if (wsSuppress_[j] != 0) continue;

            float x1_j = wsBoxes_[j * 4 + 0];
            float y1_j = wsBoxes_[j * 4 + 1];
            float x2_j = wsBoxes_[j * 4 + 2];
            float y2_j = wsBoxes_[j * 4 + 3];

            float ix1 = (curX1 > x1_j) ? curX1 : x1_j;
            float iy1 = (curY1 > y1_j) ? curY1 : y1_j;
            float ix2 = (curX2 < x2_j) ? curX2 : x2_j;
            float iy2 = (curY2 < y2_j) ? curY2 : y2_j;

            float iw = ix2 - ix1;
            float ih = iy2 - iy1;
            if (iw <= 0.0f || ih <= 0.0f) continue;

            float inter = iw * ih;
            float un = curArea + wsAreas_[j] - inter;
            if (un <= 0.0f) continue;

            float iou = inter / un;
            if (iou >= iouTh_) {
                wsSuppress_[j] = 1;
            }
        }
    }

    *outNum_ = static_cast<int32_t>(selCount);
}

// ========================== Process ==========================

__aicore__ inline void KernelNMS::Process()
{
    if (GetBlockIdx() != 0) return;

    Phase1_Filter();

    if (filteredTotal_ == 0) {
        *outNum_ = 0;
        return;
    }

    Phase2_Areas();
    Phase3_GreedyLoop();
}

// ========================== Entry Point ==========================

extern "C" __global__ __aicore__ void nms_kernel(
    GM_ADDR boxes, GM_ADDR scores,
    GM_ADDR selected_indices, GM_ADDR num_selected,
    GM_ADDR workspace, GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIV_1_0);
    if (g_coreType == AIC) return;

    auto* gt = reinterpret_cast<__gm__ NmsTiling*>(tiling);
    NmsTiling t;
    t.totalN = gt->totalN;
    t.maxOutputSize = gt->maxOutputSize;
    t.dtypeCode = gt->dtypeCode;
    t.totalCores = gt->totalCores;
    t.blockN = gt->blockN;
    t.tileN = gt->tileN;
    t.paddedN = gt->paddedN;
    t.filteredN = gt->filteredN;
    t.iouThreshold = gt->iouThreshold;
    t.scoresThreshold = gt->scoresThreshold;
    t.padOutputSize = gt->padOutputSize;

    TPipe pipe;
    KernelNMS op;
    op.Init(boxes, scores, selected_indices, num_selected, workspace, &t, &pipe);
    op.Process();
    pipe.Destroy();
}
